let project=defaultProject(),history=[],selected=null,tab='design',roomId='g-living',coverage='room',showTags=false,showRoutes=false,showCeiling=true,cameraMode='orbit',placing=false,stats,timer,activeSurface=null,anchor=null,interaction='select',drawingKind='plan';
function validate(p){
 if(!p||p.schema!==1||!Array.isArray(p.points)||p.points.length>2000||!Array.isArray(p.db)||p.db.length!==2)throw Error('Unsupported project format');
 const ids=new Set();for(const q of p.points){if(!byType[q.type]||!roomById[q.roomId]||typeof q.id!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(q.id)||ids.has(q.id)||typeof q.label!=='string'||q.label.length>120||!Object.hasOwn(surfaces,q.surface)||!['u','v','height','watts','qty'].every(k=>Number.isFinite(q[k]))||q.watts<0||q.watts>100000||!Number.isInteger(q.qty)||q.qty<1||q.qty>100||typeof q.inverter!=='boolean')throw Error('Invalid equipment data');ids.add(q.id);clampPoint(q);if(isSource(q)&&q.qty!==1)throw Error('Place sources individually, with quantity one.');if(q.phase&&!['R','Y','B'].includes(q.phase))throw Error('Invalid DB phase.');if(q.tag&&!/^E[0-9]{3,6}$/.test(q.tag))throw Error('Invalid drawing reference.');}
 if(!p.rack||![...p.db,p.rack].every(d=>d&&['x','z','height'].every(k=>Number.isFinite(d[k])))||!Number.isFinite(p.waste)||p.waste<0||p.waste>50)throw Error('Invalid calculation settings');
 if(p.designVersion&&p.designVersion!==2)throw Error('Unsupported design version');
 ensureDesign(p);
 if(!Array.isArray(p.dbIds)||p.dbIds.length!==2||!Array.isArray(p.connections)||p.connections.length>4000||!Number.isInteger(p.controlCores)||p.controlCores<0||p.controlCores>8)throw Error('Invalid sources or control settings');
 for(const [f,id] of p.dbIds.entries())if(id!==null&&!p.points.some(q=>q.id===id&&isBoard(q)&&roomById[q.roomId].floor===f))throw Error('A floor DB must be on its own floor.');
 if(p.rackId!==null&&!p.points.some(q=>q.id===p.rackId&&q.type==='rack'))throw Error('Invalid network rack');
 const linkError=connectionError(p,p.connections);if(linkError)throw Error(linkError);
 p.roomFinishes??={};for(const [id,c] of Object.entries(p.roomFinishes))if(!roomById[id]||!/^#[0-9a-f]{6}$/i.test(c))throw Error('Invalid finish');
 if(p.wireSpecs&&Object.values(p.wireSpecs).some(v=>!['TBD','1.5','2.5','4','6','10','16'].includes(String(v))))throw Error('Invalid conductor size');
 if(p.palette&&!['ivory','graphite','sand'].includes(p.palette))throw Error('Invalid palette');
 p.furnitureLayout=validateFurnitureLayout(p.furnitureLayout);
 p.compound=compoundSettings(p.compound);for(const q of p.points)if(q.customModel)validateModelReference(q.customModel);
 return p;
}
function toast(t){clearTimeout(timer);$('#toast').textContent=t;$('#toast').classList.add('show');timer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(!saved.designVersion)localStorage.setItem(KEY+'-before-visual-editor',raw);project=validate(saved);}}catch(e){try{localStorage.setItem(KEY+'-recovery',localStorage.getItem(KEY)||'');}catch{}toast('Saved design needs review; a recovery copy was retained in browser storage. '+e.message);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(project));$('#saveState').textContent=`Revision ${project.revision} · saved in this browser · export a backup`;}catch{$('#saveState').textContent='Browser save unavailable · export your project';}}
function change(fn,rebuild=false){const before=JSON.stringify(project),previousRevision=project.revision||1;try{fn();ensureDesign(project);const error=connectionError(project,project.connections);if(error)throw Error(error);project.revision=Math.max(previousRevision,project.revision||1)+1;syncSources(project);history.push(before);if(history.length>40)history.shift();persist();refresh(rebuild);return true;}catch(e){project=JSON.parse(before);refresh(true);toast(e.message);return false;}}
const r=()=>roomById[roomId],point=()=>project.points.find(p=>p.id===selected),ref=id=>project.points.find(p=>p.id===id)?.tag||'Unassigned';
