function stopPlacing(){placing=false;model.setPlacement(null,null,null);}
function setInteraction(mode){if(mode!=='select')enterRoom();if(mode==='furniture')selected=null;else if(mode!=='select')selectedFurniture=null;interaction=mode;stopPlacing();$('#dragMode').classList.toggle('active',mode==='move');$('#pickSurface').classList.toggle('active',mode==='surface');model.setInteraction(mode,{onFurniturePick:id=>selectFurnitureItem(id),onFurnitureMove:(id,coords)=>{selectedFurniture=id;selected=null;roomId=coords.roomId;$('#room').value=roomId;change(()=>{project.furnitureLayout??={};project.furnitureLayout[id]=fitFurniture(id,coords);});toast('Furniture moved and saved. Undo restores the previous position.');},onSurface:coords=>{activeSurface=coords.surface;anchor=coords;$('#addSurface').value=activeSurface;selected=null;setInteraction('select');refresh();toast(`${surfaces[activeSurface]} selected. Add hardware from the library.`);},onMove:(id,coords)=>{selected=id;roomId=point().roomId;$('#room').value=roomId;change(()=>{const p=point();Object.assign(p,coords);clampPoint(p);});toast('Moved. Drawings, routes and estimates updated.');}});furnitureControls();}
function add(type){if(type==='model'){$('#modelImport').open=true;$('#modelFiles').click();return;}const t=byType[type];if(!t)return;selectedFurniture=null;enterRoom();const surface=activeSurface||t.surface;if(r().kind==='site'&&surface==='ceiling')return toast('Choose an indoor room for ceiling fixtures.');
 const p=clampPoint(makePoint(type,roomId,{surface,...(anchor&&anchor.surface===surface?anchor:{}),...(surface==='ceiling'?{height:2.84}:{})}));if(isBoard(p))p.label=`${r().floor?'First':'Ground'} floor ${t.name}`;
 if(!change(()=>{project.points.push(p);selected=p.id;if(isBoard(p))project.dbIds[r().floor]=p.id;if(type==='rack')project.rackId=p.id;}))return;
 if(tab!=='design')setTab('design');setInteraction('select');placing=true;startPlace();inspector();toast(`${t.name} added. Click the ${surfaces[surface].toLowerCase()} to place it, then Finish placing.`);return p.id;
}
