function furnitureInspector(){
 const item=furnitureById[selectedFurniture],placement=furniturePlacement(item.id,project.furnitureLayout);
 $('#inspector').innerHTML=`<span class="tag">Furniture layout</span><h2>${esc(item.name)}</h2><p class="subtle">${item.width.toFixed(2)} × ${item.depth.toFixed(2)} m footprint · ${item.height.toFixed(2)} m high</p><label class="field">Furniture room<select id="furnitureRoom" aria-label="Furniture room">${allRooms.filter(rr=>rr.kind!=='site').map(rr=>`<option value="${rr.id}" ${rr.id===placement.roomId?'selected':''}>${rr.floor?'First':'Ground'} · ${esc(rr.name)}</option>`).join('')}</select></label><div class="fields">${[['u','Centre from left (m)'],['v','Centre from rear (m)'],['angle','Rotation (degrees)']].map(([key,name])=>`<label class="field">${name}<input data-furniture-field="${key}" aria-label="${name}" type="number" step="${key==='angle'?5:.01}" value="${Number(placement[key].toFixed(2))}"></label>`).join('')}</div><div class="buttonrow"><button id="rotateFurniture">Rotate 90°</button><button id="resetFurniture">Reset this item</button></div><p>Drag furniture across the floor in the 3D view. The complete item moves together and stays within the room footprint. Use Top for precise placement.</p><p class="subtle">Moving furniture leaves electrical and plumbing points in place. Review access and door clearances after rearranging.</p>`;
 const save=(patch,rebuild=false)=>change(()=>{const value=fitFurniture(item.id,{...furniturePlacement(item.id,project.furnitureLayout),...patch});project.furnitureLayout??={};project.furnitureLayout[item.id]=value;roomId=value.roomId;$('#room').value=roomId;},rebuild);
 $$('[data-furniture-field]').forEach(input=>input.onchange=e=>save({[e.target.dataset.furnitureField]:Number(e.target.value)}));
 $('#rotateFurniture').onclick=()=>save({angle:placement.angle+90});
 $('#furnitureRoom').onchange=e=>save({roomId:e.target.value},true);
 $('#resetFurniture').onclick=()=>change(()=>{if(project.furnitureLayout)delete project.furnitureLayout[item.id];roomId=item.roomId;$('#room').value=roomId;},true);
}
function importControls(){
 $('#modelType').innerHTML=library.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#modelType').value='model';
 $('#modelType').onchange=()=>{$('#modelWatts').value=byType[$('#modelType').value].watts;$('#modelWatts').disabled=$('#modelType').value==='model';};$('#modelType').onchange();
 $('#modelFiles').onchange=()=>{const f=[...$('#modelFiles').files].find(f=>modelFormats.includes(f.name.split('.').pop().toLowerCase()));if(f){$('#modelName').value=f.name.replace(/\.[^.]+$/,'');const format=f.name.split('.').pop().toLowerCase();$('#modelUnits').value=format==='stl'?'.001':format==='fbx'?'.01':'1';}};
 $('#addModel').onclick=async()=>{
  const files=[...$('#modelFiles').files],button=$('#addModel');if(!files.length)return toast('Choose a model file first.');
  const type=$('#modelType').value,watts=type==='model'?0:Number($('#modelWatts').value),width=Number($('#modelWidth').value),name=$('#modelName').value.trim();
  if(!Number.isFinite(watts)||watts<0||watts>100000||!Number.isFinite(width)||width<.01||width>30)return toast('Enter a valid model width and connected wattage.');
  button.disabled=true;button.textContent='Reading model…';
  try{
   const reference=await importModelFiles(files,{name,unitScale:Number($('#modelUnits').value),upAxis:$('#modelUp').value});
   reference.scale=width/Math.max(reference.dimensions[0],.000001);validateModelReference(reference);
   enterRoom();selectedFurniture=null;const t=byType[type],surface=activeSurface||t.surface,p=clampPoint(makePoint(type,roomId,{label:reference.name,customModel:reference,watts,surface}));
   if(surface==='ceiling'&&r().kind==='site')throw Error('Choose an indoor room for a ceiling-mounted model.');
   if(change(()=>{project.points.push(p);selected=p.id;if(isBoard(p))project.dbIds[r().floor]=p.id;if(type==='rack')project.rackId=p.id;})){
    setTab('design');setInteraction('select');placing=true;startPlace();inspector();toast('Model added and saved locally. Click to place it, then Finish placing.');$('#modelFiles').value='';
   }
  }catch(e){toast('Model import: '+e.message);}finally{button.disabled=false;button.textContent='Import & place';}
 };
}
function importedModelInspector(p){
 if(!p.customModel)return;const m=p.customModel;
 $('#inspector').insertAdjacentHTML('beforeend',`<div class="imported-inspector"><h3>Imported ${esc(m.format.toUpperCase())} model</h3><p class="subtle">${m.dimensions.map(v=>(v*m.scale).toFixed(2)).join(' × ')} m · width × height × depth</p><label class="field">Model width (m)<input id="customWidth" type="number" min=".01" max="30" step=".01" value="${Number((m.dimensions[0]*m.scale).toFixed(3))}"></label><label class="field">Model rotation (degrees)<input id="customAngle" type="number" step="5" value="${m.angle}"></label><button id="rotateCustom">Rotate model 90°</button><p class="subtle">Model files stay in this browser. Export project includes their files. ${p.type==='model'?'Furniture/decor adds no electrical load.':'Its assigned equipment type and wattage drive the electrical calculations.'}</p></div>`);
 $('#customWidth').onchange=e=>{const width=Number(e.target.value);if(!Number.isFinite(width)||width<.01||width>30)return toast('Enter a width from 0.01 to 30 m.');change(()=>p.customModel={...m,scale:width/Math.max(m.dimensions[0],.000001)});};
 $('#customAngle').onchange=e=>{const angle=Number(e.target.value);if(Number.isFinite(angle))change(()=>p.customModel={...m,angle:((angle%360)+360)%360});};
 $('#rotateCustom').onclick=()=>change(()=>p.customModel={...m,angle:(m.angle+90)%360});
 if(p.type==='model'){$('[data-point-field="watts"]').disabled=true;if($('#inverter'))$('#inverter').disabled=true;}
}
