function view(mode){if(coverage!=='room'&&!['top','orbit'].includes(mode))enterRoom();if(mode==='ceiling'&&r().kind==='site')mode='top';if(['A','B','C','D','ceiling'].includes(mode)&&+$('#cut').value<2.84){$('#cut').value=2.84;model.rebuild(options());if(stats)overlay();}cameraMode=mode;$$('[data-camera]').forEach(b=>b.classList.toggle('active',b.dataset.camera===mode));const angle=(+$('#orbit').value)*Math.PI/180;if(coverage!=='room')model.electricalOverview(mode,angle);else model.roomView(r(),mode,angle);}
