function totals(){$('#totals').innerHTML=`<div class="totals"><div class="stat"><b>${project.points.reduce((n,p)=>n+p.qty,0)}</b><span>Hardware / point items</span></div><div class="stat"><b>${(stats.load/1000).toFixed(2)} kW</b><span>Routed connected load</span></div><div class="stat"><b>${stats.circuits.length}</b><span>Proposed circuit groups</span></div><div class="stat"><b>${stats.controls.length}</b><span>Switch → load links</span></div></div><details class="issues"><summary>${stats.warnings.length} items needing review</summary>${stats.warnings.map(w=>`<p>${esc(w)}</p>`).join('')||'<p>No missing-source or switch-assignment warnings.</p>'}</details>`;}
function inspector(){if(selectedFurniture){furnitureInspector();return;}if(interaction==='furniture'){$('#inspector').innerHTML='<span class="tag">Move furniture</span><h2>Select an item to move.</h2><p>Click a bed, sofa, table, chair or storage unit in the model, or choose it from the furniture list above. Drag to move; select an item to rotate or enter an exact position.</p>';return;}const p=point();if(!p&&coverage!=='room'){$('#inspector').innerHTML='<span class="tag">Electrical overview</span><h2>Every point in view.</h2><p>Select hardware or its coloured marker to inspect the equipment, mounting height and supply. The list below includes all electrical and data positions in this view.</p><p class="subtle">Use Selected room for detailed placement. Point tags show the same references used in the electrical drawings.</p>';return;}if(!p){$('#inspector').innerHTML='<span class="tag">Visual electrical editor</span><h2>Choose a surface. Add real-looking hardware.</h2><ol class="quicksteps"><li>Select a room.</li><li>Choose a wall, ceiling or floor above the model.</li><li>Click + beside a library item, then click its position.</li><li>Use Drag fixtures to move items. Select a switch to connect loads.</li></ol><p class="subtle">Generic sample hardware is shown at approximate scale. Select the actual product before setting final clearances.</p>';return;}
 const networkEndpoint=['data','poe'].includes(byType[p.type].group);const c=stats.circuits.find(c=>c.points.includes(p.id)),route=stats.routes.find(q=>q.id===p.id);
 $('#inspector').innerHTML=`<span class="tag">${esc(p.tag)} · ${esc(byType[p.type].name)}</span><label class="field">Point name<input id="pointLabel" value="${esc(p.label)}" maxlength="120"></label><label class="field">Room / floor<select id="pointRoom" aria-label="Room / floor">${allRooms.map(rr=>`<option value="${rr.id}" ${rr.id===p.roomId?'selected':''}>${rr.floor?'First':'Ground'} · ${esc(rr.name)}</option>`).join('')}</select></label><label class="field">Mounting surface<select id="surface">${Object.entries(surfaces).filter(([k])=>k!=='ceiling'||r().kind!=='site').map(([k,v])=>`<option value="${k}" ${k===p.surface?'selected':''}>${v}</option>`).join('')}</select></label><div class="fields">${[['u','Across room (m)',r().dim[0]],['v','From rear (m)',r().dim[1]],['height','Height AFF (m)',2.84],['watts','Design load (W)',100000],['qty','Quantity at position',isSource(p)?1:100]].map(([k,l,max])=>`<label class="field">${l}<input data-point-field="${k}" type="number" min="${k==='qty'?1:0}" max="${max}" step="${['watts','qty'].includes(k)?1:.01}" value="${Number(p[k].toFixed(2))}" ${isBoard(p)&&k==='watts'?'disabled':''}></label>`).join('')}</div>${isBoard(p)?`<label class="field">Board type<select id="boardType"><option value="db3p" ${p.type==='db3p'?'selected':''}>Three-phase DB</option><option value="db1p" ${p.type==='db1p'?'selected':''}>Single-phase DB</option></select></label>${p.type==='db1p'?`<label class="field">Proposed incoming phase<select id="boardPhase">${['R','Y','B'].map(v=>`<option ${v===(p.phase||'R')?'selected':''}>${v}</option>`).join('')}</select></label>`:''}`:networkEndpoint?'<p class="subtle">Power follows the selected network rack supply. Set inverter readiness on the rack.</p>':`<label class="check"><input id="inverter" type="checkbox" ${p.inverter?'checked':''}>Inverter-ready / essential</label>`}<div class="buttonrow"><button id="place" class="primary">${placing?'Finish placing':'Place on view'}</button><button id="duplicate">Duplicate</button><button id="delete" class="danger">Remove</button></div><p class="subtle">Offsets use the room's rear-left corner. Heights are above finished floor. Wall A is plan-top, not compass north.</p><p class="source-note">${isBoard(p)?project.dbIds.includes(p.id)?'Active floor DB':'Placed DB · select it under Sources to use it':p.type==='rack'?'Network rack · mains feed '+(route?ref(route.sourceId):'unassigned')+'; base watts exclude attached PoE loads':route?'Returns to '+ref(route.sourceId)+' · '+(c?c.id+' / phase '+c.phase:'data / separate service'):isSwitch(p)?'Assign controlled loads below.':'No power route / separate service'}</p><div id="switchConnections"></div>`;
 $('#pointLabel').onchange=e=>change(()=>{p.label=e.target.value;if(p.customModel)p.customModel={...p.customModel,name:p.label};});
 $('#pointRoom').onchange=e=>{const next=e.target.value;enterRoom();const previousRoom=roomId;const ok=change(()=>{p.roomId=next;if(p.surface==='ceiling'&&roomById[next].kind==='site')p.surface='A';clampPoint(p);if(isBoard(p)&&project.dbIds.includes(p.id)){project.dbIds=project.dbIds.map(id=>id===p.id?null:id);project.dbIds[roomById[next].floor]=p.id;}roomId=next;$('#room').value=next;stopPlacing();},true);if(!ok){roomId=previousRoom;$('#room').value=roomId;refresh(true);}};

 $('#surface').onchange=e=>{const s=e.target.value;change(()=>{p.surface=s;if(s==='ceiling')p.height=2.84;clampPoint(p);});if(placing)startPlace();};
 if($('#inverter'))$('#inverter').onchange=e=>change(()=>p.inverter=e.target.checked);
 if($('#boardType'))$('#boardType').onchange=e=>change(()=>{p.type=e.target.value;p.phase??='R';});
 if($('#boardPhase'))$('#boardPhase').onchange=e=>change(()=>p.phase=e.target.value);
 $$('[data-point-field]').forEach(el=>el.onchange=e=>{const v=+e.target.value,k=e.target.dataset.pointField;if(!Number.isFinite(v)||v<+e.target.min||v>+e.target.max||k==='qty'&&!Number.isInteger(v)){inspector();return toast('Enter a value within the shown limits.');}change(()=>{p[k]=v;clampPoint(p);});});
 $('#place').onclick=()=>{if(placing)stopPlacing();else{setInteraction('select');placing=true;startPlace();}inspector();};
 $('#duplicate').onclick=()=>{change(()=>{const q=makePoint(p.type,p.roomId,{...p,id:makePoint(p.type,p.roomId).id,tag:undefined,u:p.u+.25,v:p.v+.25,label:(p.label+' copy').slice(0,120)});clampPoint(q);project.points.push(q);selected=q.id;});};
 $('#delete').onclick=()=>change(()=>{removePoint(project,p.id);selected=null;stopPlacing();});
 switchPanel(p);importedModelInspector(p);
}
function switchPanel(p){const container=$('#switchConnections');
 if(isSwitch(p)){
  const linked=project.connections.filter(c=>c.switchId===p.id),linkedText=linked.map(c=>`${ref(c.loadId)} ${project.points.find(q=>q.id===c.loadId)?.label}`).join(', ');
  container.innerHTML=`<h3>Controlled loads (${linked.length})</h3><p class="subtle">${esc(linkedText||'No loads linked yet.')} One station represents one control channel. Use another station for an independently switched circuit.</p><label class="field">Show loads in<select id="linkRoom"><option value="all">All rooms</option>${allRooms.map(rr=>`<option value="${rr.id}" ${rr.id===p.roomId?'selected':''}>${rr.floor?'First':'Ground'} · ${esc(rr.name)}</option>`).join('')}</select></label><div id="loadChoices" class="loadchoices"></div>`;
  const paint=()=>{const filter=$('#linkRoom').value;$('#loadChoices').innerHTML=project.points.filter(q=>isLoad(q)&&q.id!==p.id&&(filter==='all'||q.roomId===filter)).map(q=>`<label><input type="checkbox" data-link="${q.id}" ${linked.some(c=>c.loadId===q.id)?'checked':''}><span><b>${esc(q.tag)}</b> ${esc(q.label)}<small>${q.inverter?'Essential':'Normal'} · ${esc(roomById[q.roomId].name)}</small></span></label>`).join('')||'<p>No power loads in this room.</p>';$$('[data-link]').forEach(el=>el.onchange=e=>{const filter=$('#linkRoom').value;change(()=>setConnection(project,p.id,e.target.dataset.link,e.target.checked));if($('#linkRoom')){$('#linkRoom').value=filter;$('#linkRoom').dispatchEvent(new Event('change'));}});};$('#linkRoom').onchange=paint;paint();
 }else if(isLoad(p)){
  const links=project.connections.filter(c=>c.loadId===p.id);container.innerHTML=`<h3>Switches controlling this load</h3>${links.length?'<ul>'+links.map(c=>`<li>${esc(ref(c.switchId)+' · '+project.points.find(q=>q.id===c.switchId)?.label)}</li>`).join('')+'</ul>':'<p class="subtle">No manual control assigned.</p>'}<button id="addSwitch">+ Add a switch for this load</button><p class="subtle">Add another switch for a second control location. Multiway / relay terminal wiring remains an electrician's design.</p>`;
  $('#addSwitch').onclick=()=>{change(()=>{const sw=clampPoint(makePoint('switch',p.roomId,{label:('Switch for '+p.label).slice(0,120),surface:activeSurface&&!['ceiling','floor'].includes(activeSurface)?activeSurface:'D'}));project.points.push(sw);setConnection(project,sw.id,p.id,true);selected=sw.id;});placing=true;startPlace();inspector();};
 }
}
function startPlace(){const p=point();if(!p)return;enterRoom();view(p.surface==='floor'?'top':p.surface);model.setPlacement(roomById[p.roomId],p.surface,coords=>{change(()=>{Object.assign(point(),coords);clampPoint(point());});});}
function pointList(){const ps=viewPoints();$('#pointListTitle').textContent=coverage==='room'?'POINTS IN THIS ROOM':`${coverageNames[coverage].toUpperCase()} · ${ps.length} POINTS`;$('#pointList').innerHTML=ps.map(p=>`<button class="pointrow ${selected===p.id?'active':''}" data-select="${p.id}"><b>${esc(p.tag)}</b> ${esc(p.label)}<small>${coverage==='room'?'':`${roomById[p.roomId].floor?'First':'Ground'} · ${esc(roomById[p.roomId].name)} · `}${surfaces[p.surface]} · ${p.height.toFixed(2)} m AFF</small></button>`).join('');}
function dbSettings(){
 $('#dbSettings').innerHTML=`<div class="buttonrow">${project.points.filter(p=>isSource(p)&&(project.dbIds.includes(p.id)||p.id===project.rackId)).map(p=>`<button data-locate="${p.id}">Locate ${esc(p.tag)}</button>`).join('')}</div><p class="subtle">All power loads return to their own floor's selected DB. All RJ45 / PoE points return to the selected rack. Move the source hardware in 3D to update its routes.</p>${[0,1].map(f=>`<label class="field">${f?'First':'Ground'} floor DB<select data-source-db="${f}"><option value="">Unassigned</option>${project.points.filter(p=>isBoard(p)&&roomById[p.roomId].floor===f).map(p=>`<option value="${p.id}" ${project.dbIds[f]===p.id?'selected':''}>${esc(p.tag+' · '+p.label)}</option>`).join('')}</select></label>`).join('')}<label class="field">Network rack<select id="rackSource"><option value="">Unassigned</option>${project.points.filter(p=>p.type==='rack').map(p=>`<option value="${p.id}" ${p.id===project.rackId?'selected':''}>${esc(p.tag+' · '+p.label)}</option>`).join('')}</select></label><label class="field">Routing / waste allowance (%)<input id="waste" type="number" min="0" max="50" value="${project.waste}"></label><label class="field">Control conductor cores per link (engineer allowance)<input id="controlCores" type="number" min="0" max="8" step="1" value="${project.controlCores}"></label><p class="subtle">0 = unassigned, excluded from wire total. Multiple switches need a designed two-way / intermediate or relay system. A core allowance is not a terminal diagram.</p>`;
 $$('[data-locate]').forEach(b=>b.onclick=()=>{selectedFurniture=null;selected=b.dataset.locate;roomId=point().roomId;$('#room').value=roomId;enterRoom();setTab('design');refresh(true);});$$('[data-source-db]').forEach(el=>el.onchange=e=>change(()=>project.dbIds[+e.target.dataset.sourceDb]=e.target.value||null));$('#rackSource').onchange=e=>change(()=>project.rackId=e.target.value||null);
 $('#waste').onchange=e=>{const v=+e.target.value;if(Number.isFinite(v)&&v>=0&&v<=50)change(()=>project.waste=v);else dbSettings();};$('#controlCores').onchange=e=>{const v=+e.target.value;if(Number.isInteger(v)&&v>=0&&v<=8)change(()=>project.controlCores=v);else dbSettings();};
}
function brief(){const rr=r(),i=rr.kind==='site'?{title:'Outdoor service placement',text:'Boundary and gate dimensions need a site survey.'}:ideaFor(rr);
 if(coverage!=='room'){const ps=viewPoints(),count=f=>ps.filter(p=>roomById[p.roomId].floor===f).length;$('#modelCaption').textContent=`${coverageNames[coverage]} · ${ps.length} electrical / data positions · ${ps.reduce((n,p)=>n+p.qty,0)} items${point()?' · '+point().tag+' '+point().label:''}`;
 $('#overviewSummary').innerHTML=`<strong>${coverageNames[coverage]} · all electrical points</strong><span>${coverage==='all'?`Ground: ${count(0)} · First: ${count(1)} · `:''}${ps.filter(p=>p.surface==='ceiling').length} ceiling positions · wall and floor points included</span><small>${coverage==='all'?'Floors are displayed side by side for visibility. ':coverage==='ground'?'Includes the front court and side passages. ':'Includes every first-floor room and the balcony. '}Coloured markers remain visible through walls. Select a point to inspect it, or use Selected room to edit in detail.</small>`;
 $('#roomBrief').innerHTML='<p>Scroll to zoom and drag to orbit. Top fits every point in this view; Orbit shows mounting heights. Point tags reveal the drawing references. Plumbing-only provisions are omitted from this electrical overview.</p>'+(coverage==='all'?'<p class="subtle">The separation is only for viewing. Actual equipment coordinates, inter-floor routes, drawings and BOM calculations are unchanged.</p>':'');return;}
 $('#modelCaption').textContent=`${rr.floor?'First':'Ground'} · ${rr.name} · ${rr.dim.map(v=>v.toFixed(2)).join(' × ')} m · generic sample hardware`;
 $('#roomBrief').innerHTML=`<b>${esc(i.title)}</b><p>${esc(i.text)}</p><p class="subtle">Drag fixtures moves the hardware along its mounting surface in 50 mm steps. Choose another mounting surface in the inspector to move it to a different wall or ceiling. Drawings and schedules update when you release it.</p>`;
}
function setTab(t){tab=t;stopPlacing();$('#designPanel').hidden=t!=='design';$('#report').hidden=t==='design';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));if(t==='design'){rebuild();overlay();}else report();}
function bomRows(){const rows=stats.bom.slice(),groups={},wall=compoundQuantities(project.compound);for(const f of resolvedFurniture(project.furnitureLayout))rows.push({name:'Furniture · '+f.name,qty:1,unit:'pcs',note:roomById[f.roomId].name+' · '+f.width.toFixed(2)+' × '+f.depth.toFixed(2)+' m · centre '+f.u.toFixed(2)+', '+f.v.toFixed(2)+' m · rotation '+f.angle+'°; concept size.'});rows.push({name:'Compound wall · net length',qty:wall.length,unit:'m',note:'Three-sided wall excluding the gate opening; rear boundary not included.'},{name:'Compound wall · finish on two faces',qty:wall.finishArea,unit:'m²',note:'Concept net area only; piers, footings, coping, thickness and waste require a measured takeoff.'},{name:'Sliding gate · face area',qty:wall.gateArea,unit:'m²',note:'Opening width × modelled gate height; track/runback and hardware need site design.'});for(const c of stats.circuits){const size=project.wireSpecs?.[c.key]||'TBD';groups[size]=(groups[size]||0)+c.wireLength*(1+project.waste/100);}for(const [s,qty] of Object.entries(groups))rows.push({name:`Conductor subset · ${s==='TBD'?'size unassigned':s+' mm² user-assigned'}`,qty,unit:'m',note:'Subset of final-circuit conductor total; do not add again. Control allowance is separate within that total.'});for(const rr of allRooms)rows.push({name:`${rr.floor?'First':'Ground'} ${rr.name} · floor finish`,qty:rr.dim[0]*rr.dim[1]*(1+project.waste/100),unit:'m²',note:'Labelled rectangular area plus allowance; actual tile takeoff and openings need measurement.'});return rows;}
function report(){
 const actions='<div class="buttonrow"><button data-pack class="primary">Download engineer pack</button><button data-export="points">Point schedule CSV</button><button data-export="controls">Switch schedule CSV</button></div>';
 if(tab==='drawings'){
  $('#report').innerHTML=`<span class="tag">Live drawing · revision ${project.revision}</span><h1>Electrical drawings</h1>${actions}<div class="buttonrow"><select id="drawingKind" aria-label="Drawing type"><option value="plan">Floor electrical plan</option><option value="ceiling">Ceiling points</option><option value="wall">Selected room wall elevation</option><option value="topology">DB / circuit diagram</option></select><button id="saveSvg">Download SVG</button></div><div id="drawingOutput"></div><p class="subtle">Use the room dropdown to change the floor / room. For an elevation, choose Wall A/B/C/D under Add onto. Exported pack includes both floors, ceiling sheets, point / switch schedules, circuit groups, BOM and route coordinates.</p>`;
  $('#drawingKind').value=drawingKind;const paint=()=>{$('#drawingOutput').innerHTML=drawingKind==='topology'?topology(project,stats):drawing(project,stats,{floor:r().floor,kind:drawingKind,roomId:drawingKind==='wall'?roomId:null,surface:['A','B','C','D'].includes(activeSurface)?activeSurface:'A'});};paint();$('#drawingKind').onchange=e=>{drawingKind=e.target.value;paint();};$('#saveSvg').onclick=()=>download(`myhome-${drawingKind}-R${project.revision}.svg`,$('#drawingOutput').innerHTML,'image/svg+xml');
 }else if(tab==='circuits'){
  $('#report').innerHTML=`<span class="tag">Live circuits and control links</span><h1>Sources, circuits & switching</h1>${actions}<p>Each floor uses its selected DB; RJ45 and PoE cables return to the selected rack. A network rack's power circuit includes its base watts plus attached PoE watts. Socket current ratings are hardware labels: enter the actual connected load separately.</p><div class="cards">${Object.entries(stats.phase).map(([p,w])=>`<div class="stat"><b>${p} · ${(w/1000).toFixed(2)} kW</b><span>Proposed phase load</span></div>`).join('')}</div><button data-export="circuits">Circuit schedule CSV</button>${table(['Circuit','DB','Room','Supply / phase','W','Points','Route m'],stats.circuits.map(c=>[c.id,ref(c.sourceId),c.room,(c.essential?'Essential':'Normal')+' / '+c.phase,c.watts.toFixed(0),c.points.map(ref).join(', '),c.length.toFixed(2)]))}<h3>Switch-to-load schedule</h3>${table(controlHeaders,controlRows(project,stats))}<h3>User-assigned conductor sizes</h3><div class="wireassign">${stats.circuits.map(c=>`<label>${esc(c.id)}<select data-wire="${esc(c.key)}">${['TBD','1.5','2.5','4','6','10','16'].map(v=>`<option value="${v}" ${String(project.wireSpecs?.[c.key]||'TBD')===v?'selected':''}>${v==='TBD'?'Unassigned':v+' mm²'}</option>`).join('')}</select></label>`).join('')}</div><p class="subtle">Cable capacity, protective devices, voltage drop and control terminal wiring are not designed by this tool. Essential groups on a three-phase DB use a provisional R phase; backup architecture needs engineering.</p>`;
  $$('[data-wire]').forEach(el=>el.onchange=e=>change(()=>{project.wireSpecs??={};project.wireSpecs[e.target.dataset.wire]=e.target.value;}));
 }else if(tab==='bom'){
  $('#report').innerHTML=`<span class="tag">Live material estimate</span><h1>Equipment & routing allowances</h1>${actions}<button data-export="bom">Export BOM CSV</button>${table(['Material','Quantity','Unit','Basis'],bomRows().map(b=>[b.name,b.qty.toFixed(2),b.unit,b.note]))}<h3>Calculation basis</h3><p>Independent power endpoint route + 2 m slack, × 3 conductors × quantity. Each RJ45 connector has one rack home run. Control links use ${project.controlCores} user-assigned cores (0 excludes them). ${project.waste}% allowance is applied. Conduit routes are independent allowances, without shared-run optimisation.</p><div class="callout">${esc(stats.excluded)}</div>`;
 }else finishReport();
 $$('[data-pack]').forEach(b=>b.onclick=pack);$$('[data-export]').forEach(b=>b.onclick=()=>exportCSV(b.dataset.export));
}
const materials=[['Ivory stone','#d2cabb','600 × 1200 mm porcelain study','linear-gradient(45deg,#d5cdbd,#eee9dc 50%,#c6beac)'],['Warm microcement','#b8b6a9','Seamless mineral floor study','linear-gradient(115deg,#b3b4a9,#d3d1c5)'],['Light oak','#b99b77','Timber-look flooring','repeating-linear-gradient(90deg,#b99b77 0px,#c7ad89 4px,#b4936a 8px,#c7aa84 12px)'],['Smoked walnut','#8e7051','Timber-look flooring','repeating-linear-gradient(90deg,#8e7051 0px,#a18869 5px,#806348 8px)'],['Charcoal stone','#737a71','Matte stone study','linear-gradient(45deg,#7a8179,#626d64)'],['Pale terrazzo','#d1cec0','Fine aggregate floor study','radial-gradient(#989b89 1px,transparent 2px) 0 0/12px 12px,#dedacf'],['Sage mineral','#a5af9a','Muted colour floor study','linear-gradient(45deg,#a5af9a,#bec6b1)'],['Sand limestone','#c6b396','Warm low-contrast stone','linear-gradient(35deg,#c6b396,#deccb1)']];
function finishReport(){$('#report').innerHTML=`<span class="tag">Modern, restrained material direction</span><h1>Warm minimalism, with precise edges</h1><p>The supplied render references suggest light stone, warm timber, dark details and integrated lighting. Use one calm wall colour, a continuous matte floor, flush joinery and a few recessed accents. Keep decorative panels selective so the existing geometry remains the focus.</p><h3>Whole-house palette</h3><div class="buttonrow">${[['ivory','Ivory / oak'],['graphite','Stone / graphite'],['sand','Sand / walnut']].map(([id,n])=>`<button data-palette="${id}" class="${(project.palette||'ivory')===id?'active':''}">${n}</button>`).join('')}</div><h3>Room flooring · ${r().name}</h3><input id="materialSearch" type="search" placeholder="Search stone, oak, terrazzo…" aria-label="Search material library"><div id="materials" class="cards" style="margin-top:12px"></div><h3>Photo-based exterior direction</h3><img style="width:100%;border-radius:7px" src="assets/exterior-minimal-v2.png" alt="New minimalist exterior finish illustration based on the actual house photo"><p class="subtle">AI finish study: retains the major facade lines, with inferred ground/steps and landscaping. Boundary dimensions are governed by the measured site study, not this image. <a href="assets/exterior-minimal-prompt.txt" target="_blank">Prompt and provenance</a></p><h3>Your sample references</h3><div class="photopair"><img src="assets/sample-render-1.jpg" alt="Owner-supplied exterior reference with light facade, natural timber and front court"><img src="assets/sample-render-2.jpg" alt="Owner-supplied evening exterior reference with warm integrated lighting"></div><p class="subtle">The supplied images are style references, not verified construction details. The sample PDF also differs from the original upstairs bathroom arrangement; the dimensioned original plan remains the model baseline pending your choice. Roof additions, equipment, boundary and ornamental panels are not assumed to exist.</p><p><a href="assets/sample-top-view.pdf" target="_blank">Open the supplied two-page interior top-view reference</a></p><h3>Apply the direction consistently</h3><ul><li>Walls: smooth warm off-white; a limited stone or limewash accent, after moisture repairs.</li><li>Kitchen: handleless muted fronts, thin-looking light worktop, continuous backsplash and accessible under-cabinet lighting.</li><li>Prayer: quiet wall wash and a shallow freestanding panel; retain the user's ritual orientation and clear floor area.</li><li>Bedrooms: flat wardrobes, recessed pulls, slim floating bedside shelves and separately controlled warm bedside lights.</li><li>Ceilings: shallow perimeter light detail only where measured headroom allows; retain access to drivers and service junctions.</li><li>Exterior: light plaster, one muted recess colour and aligned timber/metal accents; retain columns, windows and slab lines.</li></ul><div class="callout">The browser uses procedural material patterns for visual comparison. Product brands, slip resistance, wet-area suitability, durability, actual samples and installation systems remain to be selected.</div>`;
 const draw=()=>{const q=$('#materialSearch').value.toLowerCase();$('#materials').innerHTML=materials.filter(m=>m.join(' ').toLowerCase().includes(q)).map(m=>`<button class="materialcard" data-material="${m[1]}"><div class="sample" style="background:${m[3]}"></div>${m[0]}<small>${m[2]}</small></button>`).join('');$$('[data-material]').forEach(b=>b.onclick=()=>{change(()=>project.roomFinishes[roomId]=b.dataset.material,true);toast('Room flooring updated. Return to Place & inspect to see it.');});};draw();$('#materialSearch').oninput=draw;$$('[data-palette]').forEach(b=>b.onclick=()=>{change(()=>project.palette=b.dataset.palette,true);toast('Whole-house palette updated.');});}

function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function pack(){download(`myhome-engineer-pack-R${project.revision}.html`,engineerPack(project,stats,bomRows()),'text/html;charset=utf-8');toast('Engineer pack exported. Open it locally to print / save as PDF.');}
const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';
function exportCSV(kind){let rows;if(kind==='bom')rows=[['Item','Quantity','Unit','Basis'],...bomRows().map(b=>[b.name,b.qty.toFixed(2),b.unit,b.note]),['EXCLUSIONS','','',stats.excluded]];else if(kind==='controls')rows=[controlHeaders,...controlRows(project,stats)];else if(kind==='circuits')rows=[['Circuit','DB','Floor','Room','Supply','Phase','W','Route m','Wire mm2','Points'],...stats.circuits.map(c=>[c.id,ref(c.sourceId),c.floor,c.room,c.essential?'Essential':'Normal',c.phase,c.watts,c.length.toFixed(2),project.wireSpecs?.[c.key]||'UNASSIGNED',c.points.map(ref).join(' | ')])];else rows=[pointHeaders,...pointRows(project,stats)];download(`myhome-${kind}-R${project.revision}.csv`,'\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add)add(b.dataset.add);else if(b.dataset.coverage)setCoverage(b.dataset.coverage);else if(b.dataset.select)selectPoint(b.dataset.select);else if(b.dataset.tab)setTab(b.dataset.tab);else if(b.dataset.camera)view(b.dataset.camera);});
$('#moveFurniture').onclick=()=>{if(interaction==='furniture'||interaction==='move'&&point()?.type==='model'){setInteraction('select');inspector();}else{enterRoom();setInteraction(point()?.type==='model'?'move':'furniture');view('top');inspector();}};$('#finishFurniture').onclick=()=>{setInteraction('select');inspector();};$('#furnitureChoice').onchange=e=>{const id=e.target.value;if(id.startsWith('point:')){enterRoom();selectPoint(id.slice(6));setInteraction('move');view('top');}else if(id)selectFurnitureItem(id,true);};
$('#search').oninput=catalog;$('#category').onchange=catalog;$('#room').onchange=e=>selectRoom(e.target.value);$('#pointTags').onchange=e=>{showTags=e.target.checked;overlay();};$('#expandModel').onclick=()=>{const expanded=document.body.classList.toggle('expanded-model');$('#expandModel').textContent=expanded?'Show side panels':'Expand model';$('#expandModel').setAttribute('aria-pressed',String(expanded));requestAnimationFrame(()=>view(cameraMode));};$('#routes').onchange=e=>{showRoutes=e.target.checked;overlay();};$('#ceiling').onchange=e=>{showCeiling=e.target.checked;overlay();};$('#orbit').oninput=()=>view('orbit');$('#cut').oninput=()=>{model.rebuild(options());overlay();};
$('#addSurface').onchange=e=>{const nextSurface=e.target.value||null;enterRoom();activeSurface=nextSurface;anchor=null;setInteraction('select');if(activeSurface)view(activeSurface==='floor'?'top':activeSurface);overlay();if(tab!=='design')report();};$('#pickSurface').onclick=()=>{setInteraction(interaction==='surface'?'select':'surface');toast('Click a wall, ceiling or floor in the selected room, then add hardware.');};$('#dragMode').onclick=()=>setInteraction(interaction==='move'?'select':'move');$('#stopPlace').onclick=()=>{stopPlacing();setInteraction('select');inspector();};
$('#undo').onclick=()=>{if(!history.length)return toast('Nothing to undo.');const nextRevision=project.revision+1;project=validate(JSON.parse(history.pop()));project.revision=nextRevision;selected=null;selectedFurniture=null;stopPlacing();persist();refresh(true);};$('#saveFile').onclick=async()=>{const button=$('#saveFile');button.disabled=true;button.textContent='Preparing backup…';try{download(`myhome-design-R${project.revision}.json`,JSON.stringify(await portableProject(project),null,2));toast('Project backup exported, including imported model files.');}catch(e){toast(e.message);}finally{button.disabled=false;button.textContent='Export project';}};$('#downloadPack').onclick=pack;
$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>180*1024*1024)throw Error('Project backup exceeds 180 MB');const imported=validate(JSON.parse(await f.text()));await restoreModelBundle(imported);change(()=>{project=imported;selected=null;selectedFurniture=null;stopPlacing();},true);toast('Project imported. Sources, switch links and drawings restored.');}catch(err){toast('Import failed: '+err.message);}e.target.value='';};
catalog();importControls();coverageControls();persist();refresh(true);setInteraction('select');
const query=new URLSearchParams(location.search);if(roomById[query.get('room')])selectRoom(query.get('room'));if(project.points.some(p=>p.id===query.get('point'))){selected=query.get('point');roomId=point().roomId;$('#room').value=roomId;refresh(true);}
if(Object.hasOwn(coverageNames,query.get('view')))setCoverage(query.get('view'));
const initialTab=query.get('tab');if(['design','circuits','drawings','bom','finishes'].includes(initialTab))setTab(initialTab);
try{document.modelContext?.registerTool({name:'configure_design_studio',title:'Configure visual electrical studio',description:'Select room, surface or view; optionally add a fixture to the browser-local design. Does not publish or approve wiring.',inputSchema:{type:'object',properties:{room:{type:'string',enum:allRooms.map(r=>r.id)},coverage:{type:'string',enum:Object.keys(coverageNames)},camera:{type:'string',enum:['orbit','top','ceiling','A','B','C','D']},tab:{type:'string',enum:['design','circuits','drawings','bom','finishes']},addType:{type:'string',enum:library.map(t=>t.id)}},additionalProperties:false},execute:async input=>{if(input.room&&!roomById[input.room]||input.addType&&!byType[input.addType])throw Error('Invalid configuration');if(input.room)selectRoom(input.room);if(input.coverage)setCoverage(input.coverage);if(input.tab)setTab(input.tab);if(input.camera)view(input.camera);const id=input.addType?add(input.addType):null;return {room:roomId,coverage,visiblePoints:viewPoints().length,tab,pointId:id,points:project.points.length,circuits:stats.circuits.length};}});}catch{}
